 correctly.'=>'jQuery wurde nicht ordnungsgemäß geladen oder ist nicht verfügbar. AJAX- und interaktive Formularfunktionen funktionieren möglicherweise nicht richtig.','job application forms'=>'Bewerbungsformulare','location picker form'=>'Formular zur Standortauswahl','multi-step form plugin'=>'Plugin für mehrstufige Formulare','not provided by PHP or its required extension:'=>'nicht von PHP oder einer erforderlichen Erweiterung bereitgestellt:','not provided by PHP or its required extension: %s'=>'nicht bereitgestellt durch PHP oder eine erforderliche Erweiterung: %s','offline WordPress forms'=>'Offline-Formulare für WordPress','one time'=>'einmalig','or'=>'oder','or choose a template from the Templates panel'=>'oder wähle eine Vorlage aus dem Vorlagenbereich aus','or click here'=>'oder klicke hier','out of 100'=>'von 100','payment form plugin'=>'Plugin für Zahlungsformulare','persiaPayment'=>'persiaPayment','points'=>'Punkte','premium experience'=>'ein erstklassiges Erlebnis','product'=>'Produkt','reCAPTCHA'=>'reCAPTCHA','reCAPTCHA v2'=>'reCAPTCHA v2','recurring payment forms'=>'Formulare für wiederkehrende Zahlungen','red'=>'Rot','reset'=>'zurücksetzen','result'=>'Ergebnis','results'=>'Ergebnisse','secure WordPress forms'=>'Sichere WordPress-Formulare','selected'=>'ausgewählt','self-hosted WordPress forms'=>'Selbst gehostete WordPress-Formulare','shortcode_message is required!'=>'„shortcode_message“ ist erforderlich!','silentCAPTCHA Spam Protection'=>'silentCAPTCHA Spam-Schutz','smart forms WordPress'=>'Intelligente WordPress-Formulare','subscription payment forms'=>'Zahlungsformulare für Abonnements','survey form plugin'=>'Plugin für Umfrageformulare','terms'=>'Geschäftsbedingungen','the downloaded file was damaged'=>'Die heruntergeladene Datei war beschädigt','the language server answered with an error'=>'Der Sprachserver hat mit einem Fehler geantwortet','the server this website runs on cannot connect to %s'=>'Der Server, auf dem diese Website läuft, kann kei